// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(uint256 value) public {
        vm.assume(value > 0);
        StateModifier helper = new StateModifier(value);
        bool ok;
        try c.forward(address(helper), abi.encodeWithSignature("store(uint256)", value)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract StateModifier {
    uint256 public stored;
    constructor(uint256 val) { stored = val; }
    function store(uint256 val) external payable {
        stored = val;
    }
}
